const incoming = $input.first().json ?? {};
const payload = incoming.body && typeof incoming.body === 'object'
  ? incoming.body
  : incoming;
const preferences = payload.preferences && typeof payload.preferences === 'object'
  ? payload.preferences
  : {};

return [{ json: {
  ingredients: Array.isArray(payload.ingredients) ? payload.ingredients : [],
  servings: Number(payload.servings ?? preferences.portions ?? 0),
  helpers: Number(payload.helpers ?? preferences.persons ?? 0),
  timeCategoryRaw: payload.timeCategory ?? preferences.cookingTime ?? 'medium',
  cuisineRaw: payload.cuisine ?? preferences.cuisine ?? '',
  dietRaw: payload.diet ?? preferences.diet ?? 'none'
} }];

const item = $input.first().json;
const errors = [];
const validCuisines = ['de', 'it', 'jp', 'in', 'gourmet', 'fusion'];
const validDiets = ['vegetarian', 'vegan', 'keto', 'none'];
const validTimeCategories = ['quick', 'medium', 'elaborate'];
const rawIngredients = Array.isArray(item.ingredients) ? item.ingredients : [];

const normalizedIngredients = rawIngredients.map((ingredient) => {
  const structured = typeof ingredient === 'object' && ingredient !== null;
  const name = structured ? String(ingredient.name ?? '').trim() : String(ingredient ?? '').trim();
  const amount = structured ? Number(ingredient.amount) : null;
  const unit = structured ? String(ingredient.unit ?? '').trim() : '';
  return { name, amount, unit, structured };
});

const ingredientIsValid = (ingredient) => {
  const normalizedName = ingredient.name.toLowerCase();
  const validName = ingredient.name.length >= 2 && /[a-zA-ZäöüÄÖÜß]/.test(ingredient.name) &&
    !/^\d+$/.test(ingredient.name) && !['test', 'asdf', 'qwe'].includes(normalizedName);
  const validQuantity = !ingredient.structured ||
    (Number.isFinite(ingredient.amount) && ingredient.amount > 0 && ingredient.unit.length > 0);
  return validName && validQuantity;
};

if (normalizedIngredients.length === 0) errors.push('At least one valid ingredient is required');
if (normalizedIngredients.some((ingredient) => !ingredientIsValid(ingredient))) {
  errors.push('Each ingredient requires a valid name, positive amount, and unit');
}
if (!Number.isInteger(item.servings) || item.servings < 1 || item.servings > 12) {
  errors.push('servings must be between 1 and 12');
}
if (!Number.isInteger(item.helpers) || item.helpers < 1 || item.helpers > 3) {
  errors.push('helpers must be between 1 and 3');
}
if (!validCuisines.includes(item.cuisine)) errors.push('cuisine is invalid');
if (!validTimeCategories.includes(item.timeCategory)) errors.push('timeCategory is invalid');
const diet = item.diet || 'none';
if (!validDiets.includes(diet)) errors.push('diet is invalid');

return [{ json: {
  ...item,
  ingredients: normalizedIngredients
    .filter(ingredientIsValid)
    .map(({ name, amount, unit }) => ({ name, amount, unit })),
  diet,
  valid: errors.length === 0,
  errors
} }];

const item = $input.first().json;

const headers = $('Webhook').first().json.headers || {};

const forwardedFor = headers['x-forwarded-for'];
const realIp = headers['x-real-ip'];

let ip = 'unknown';

if (typeof forwardedFor === 'string' && forwardedFor.trim()) {
  ip = forwardedFor.split(',')[0].trim();
} else if (typeof realIp === 'string' && realIp.trim()) {
  ip = realIp.trim();
} else if (typeof headers.host === 'string' && headers.host.includes('localhost')) {
  ip = '127.0.0.1';
}

const now = new Date();
const dateKey = now.toISOString().slice(0, 10);
const quotaKey = `${ip}_${dateKey}`;

return [
  {
    json: {
      ...item,
      quota: {
        ip,
        dateKey,
        quotaKey,
        limitPerDay: 3,
        requestCost: 3
      }
    }
  }
];

const item = $input.first().json;

return [
  {
    json: {
      ...item,
      generationPlan: {
        includeLibraryRecipe: false,
        generateCount: 3
      }
    }
  }
];

const item = $input.first().json;

const promptData = {
  ingredients: item.ingredients || [],
  servings: item.servings,
  helpers: item.helpers,
  timeCategory: item.timeCategory,
  cuisine: item.cuisine,
  diet: item.diet,
  generateCount: 3,
  libraryContext: null
};

return [
  {
    json: {
      ...item,
      promptData
    }
  }
];

const item = $input.first().json;
const data = item.promptData;

const ingredientsText = (data.ingredients || [])
  .map((ingredient) => {
    const amount = ingredient.amount ?? '';
    const unit = ingredient.unit ?? '';
    const name = ingredient.name ?? '';
    return `- ${amount} ${unit} ${name}`.trim();
  })
  .join('\n');

const libraryContextText = data.libraryContext
  ? `
Existing library recipe already found:
- id: ${data.libraryContext.id}
- title: ${data.libraryContext.title}
- ingredients: ${(data.libraryContext.ingredients || []).join(', ')}
- cuisine: ${data.libraryContext.cuisine}
- diet: ${data.libraryContext.diet}
- timeCategory: ${data.libraryContext.timeCategory}

Generate new alternatives that are meaningfully different from this existing recipe.
`
  : `No existing library recipe was found.`;

const prompt = `
You are a recipe generation system.

Generate exactly ${data.generateCount} new recipe alternatives.

User constraints:
- servings: ${data.servings}
- helpers: ${data.helpers}
- timeCategory: ${data.timeCategory}
- cuisine: ${data.cuisine}
- diet: ${data.diet}

User ingredients:
${ingredientsText}

${libraryContextText}

Rules:
- Return valid JSON only.
- Do not return markdown.
- Generate exactly ${data.generateCount} recipes.
- Each recipe should use at least 70% of the provided user ingredients when possible.
- Each recipe may add at most 3 extra basic ingredients.
- The recipes must be clearly distinct from each other.
- If a library recipe is provided, the new recipes must be different from it.
- Steps must be chronological and easy to follow.
- Include helper task assignment for up to ${data.helpers} people.
- Include nutrition estimates.
- Nutrition must contain perPortion and total.
- Each nutrition object must include:
  calories, protein_g, carbs_g, fat_g

Return this JSON shape:
{
  "recipes": [
    {
      "title": "string",
      "description": "string",
      "servings": number,
      "cookTimeMinutes": number,
      "timeCategory": "quick | medium | elaborate",
      "cuisine": "de | it | jp | in | gourmet | fusion",
      "diet": "vegetarian | vegan | keto | none",
      "difficulty": "easy | medium | hard",
      "tags": ["string"],
      "ingredients": [
        {
          "name": "string",
          "amount": number,
          "unit": "string",
          "source": "user | extra"
        }
      ],
      "extraIngredients": [
        {
          "name": "string",
          "amount": number,
          "unit": "string",
          "reason": "basic"
        }
      ],
      "steps": [
        {
          "index": number,
          "title": "string",
          "description": "string",
          "durationMinutes": number,
          "parallelizable": true,
          "assignedTo": ["cook_1"]
        }
      ],
      "helperAssignments": [
        {
          "person": "cook_1",
          "stepIndexes": [1, 2]
        }
      ],
      "nutrition": {
        "perPortion": {
          "calories": number,
          "protein_g": number,
          "carbs_g": number,
          "fat_g": number
        },
        "total": {
          "calories": number,
          "protein_g": number,
          "carbs_g": number,
          "fat_g": number
        }
      }
    }
  ]
}
`.trim();

return [
  {
    json: {
      ...item,
      aiPrompt: prompt
    }
  }
];

const item = $input.first().json;

let parsed = null;
let rawText = '';

// Fall 1: n8n/Gemini liefert bereits fertiges JSON
if (item.content && typeof item.content === 'object' && !Array.isArray(item.content)) {
  parsed = item.content;
}

// Fall 2: content ist bereits ein JSON-Array
else if (Array.isArray(item.content)) {
  parsed = item.content;
}

// Fall 3: Gemini liefert Text in content.parts[0].text
else if (typeof item.content?.parts?.[0]?.text === 'string') {
  rawText = item.content.parts[0].text;
}

// Fall 4: Gemini liefert direkt text
else if (typeof item.text === 'string') {
  rawText = item.text;
}

// Fall 5: n8n liefert output als Text
else if (typeof item.output === 'string') {
  rawText = item.output;
}

// Fall 6: output ist bereits JSON
else if (item.output && typeof item.output === 'object') {
  parsed = item.output;
}

// Wenn wir Text bekommen haben, JSON daraus machen
if (!parsed && rawText) {
  let cleanedText = rawText.trim();

  // Falls Gemini trotz Anweisung Markdown-Codeblöcke zurückgibt
  cleanedText = cleanedText
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  try {
    parsed = JSON.parse(cleanedText);
  } catch (error) {
    throw new Error(
      `Failed to parse AI JSON response: ${error.message}`
    );
  }
}

// Keine verwertbare Antwort
if (!parsed) {
  throw new Error('No valid AI JSON response found');
}

// Einheitliche Struktur sicherstellen
if (Array.isArray(parsed)) {
  parsed = {
    recipes: parsed
  };
}

if (!Array.isArray(parsed.recipes)) {
  throw new Error('AI response does not contain a recipes array');
}

return [
  {
    json: {
      ...item,
      aiRawText: rawText || null,
      aiParsed: parsed
    }
  }
];

const item = $input.first().json;

const recipes = Array.isArray(item.aiParsed?.recipes) ? item.aiParsed.recipes : [];

const generatedRecipes = recipes.map((recipe, index) => {
  const normalizedIngredients = Array.isArray(recipe.ingredients)
    ? recipe.ingredients.map((ingredient) => ({
        name: String(ingredient.name || '').trim(),
        amount: ingredient.amount ?? null,
        unit: ingredient.unit ?? '',
        source: ingredient.source === 'extra' ? 'extra' : 'user'
      }))
    : [];

  const normalizedExtraIngredients = Array.isArray(recipe.extraIngredients)
    ? recipe.extraIngredients.map((ingredient) => ({
        name: String(ingredient.name || '').trim(),
        amount: ingredient.amount ?? null,
        unit: ingredient.unit ?? '',
        reason: ingredient.reason || 'basic'
      }))
    : [];

  const normalizedSteps = Array.isArray(recipe.steps)
    ? recipe.steps.map((step, stepIndex) => ({
        index: step.index ?? stepIndex + 1,
        title: String(step.title || '').trim(),
        description: String(step.description || '').trim(),
        durationMinutes: step.durationMinutes ?? null,
        parallelizable: Boolean(step.parallelizable),
        assignedTo: Array.isArray(step.assignedTo) ? step.assignedTo : []
      }))
    : [];

  const helperAssignments = Array.isArray(recipe.helperAssignments)
    ? recipe.helperAssignments.map((assignment) => ({
        person: assignment.person || 'cook_1',
        stepIndexes: Array.isArray(assignment.stepIndexes) ? assignment.stepIndexes : []
      }))
    : [];

  return {
    source: 'generated',
    tempId: `generated_${index + 1}`,
    title: String(recipe.title || '').trim(),
    description: String(recipe.description || '').trim(),
    servings: recipe.servings ?? item.servings,
    cookTimeMinutes: recipe.cookTimeMinutes ?? null,
    timeCategory: recipe.timeCategory || item.timeCategory,
    cuisine: recipe.cuisine || item.cuisine,
    diet: recipe.diet || item.diet,
    difficulty: recipe.difficulty || 'medium',
    tags: Array.isArray(recipe.tags) ? recipe.tags : [],
    ingredients: normalizedIngredients,
    extraIngredients: normalizedExtraIngredients,
    steps: normalizedSteps,
    helperAssignments,
    nutrition: recipe.nutrition || {
      perPortion: {
        calories: null,
        protein_g: null,
        carbs_g: null,
        fat_g: null
      },
      total: {
        calories: null,
        protein_g: null,
        carbs_g: null,
        fat_g: null
      }
    }
  };
});

return [
  {
    json: {
      ...item,
      generatedRecipes
    }
  }
];

const item = $input.first().json;

return [
  {
    json: {
      ...item,
      recipes: Array.isArray(item.generatedRecipes) ? item.generatedRecipes : []
    }
  }
];

const recipesItem = $('Build Final Recipes List').first().json;
const quotaItem = $('Normalize Quota Counter').first().json;

const recipes = Array.isArray(recipesItem.recipes)
  ? recipesItem.recipes
  : [];

return [
  {
    json: {
      success: true,
      libraryMatch: {
        hasMatch: recipesItem.libraryMatch?.hasMatch ?? false,
        bestMatchId: recipesItem.libraryMatch?.bestMatch?.id ?? null
      },
      quota: quotaItem.quota ?? null,
      recipes
    }
  }
];

const item = $input.first().json;

const recipes = Array.isArray(item.aiParsed?.recipes) ? item.aiParsed.recipes : [];
const expectedCount = item.generationPlan?.generateCount ?? 3;

const valid = recipes.length === expectedCount;

return [
  {
    json: {
      ...item,
      generationCountCheck: {
        expected: expectedCount,
        actual: recipes.length,
        valid
      }
    }
  }
];

